	/// <summary>
    /// PaffH 01.06.21
    /// </summary>
    /// <returns>concatination title1 + title2</returns>
    [SysClientCacheDataMethodAttribute]
	public display NDXEcoResProductTitle title()
    {
        NDXEcoResProductTitle title1 = next Title();
        NDXEcoResProductTitle title2 = EcoResProductTranslation::getNameOrDefaultNameConcat(this.Product);

        return title2 ? strFmt('%1 : %2', this.ItemId, title2) : title1;
    }

    /// <summary>
    /// Checks if product is a dummy product
    /// </summary>
    /// <param name = "_itemId">ItemId</param>
    /// <returns>true or false</returns>
	static public boolean isDummy(ItemId _itemId)
    {
        InventTable inventtable = InventTable::find(_itemId);
        EcoResCategoryHierarchy ecoResCategoryHierarchy = EcoResCategoryHierarchy::findByName('Dummy');
        EcoResProductCategory ecoResProductCategory;

        if(inventtable && ecoResCategoryHierarchy)
        {
            ecoResProductCategory = EcoResProductCategory::findByProductAndCategoryHierarchy(inventtable.Product, ecoResCategoryHierarchy.RecId);
        }
        return ecoResProductCategory ? true:false;
    }

