/// <summary>
/// gets a gross selling price
/// </summary>
/// <returns>Price</returns>
public Price NDX_BruttoVKP()
{
    PriceDiscTable priceDiscTable;
    InventTableModule inventTableModule;
    AvaSalesParameters AVASalesParameters = AvaSalesParameters::find();

    select firstonly priceDiscTable
        where priceDiscTable.ItemRelation == this.ItemId
            && priceDiscTable.AccountCode == PriceDiscPartyCodeType::GroupId
            && priceDiscTable.relation == PriceType::PriceSales
            && priceDiscTable.AccountRelation  == AVASalesParameters.CustPriceGroup
            && priceDiscTable.ToDate >= DateTimeUtil::getToday(DateTimeUtil::getUserPreferredTimeZone());

    if(!priceDiscTable)
    {
        select firstonly priceDiscTable
            where priceDiscTable.ItemRelation == this.ItemId
            && priceDiscTable.AccountCode == PriceDiscPartyCodeType::GroupId
            && priceDiscTable.relation == PriceType::PriceSales
                && priceDiscTable.AccountRelation == AVASalesParameters.CustPriceGroup
                && !priceDiscTable.ToDate;
    }

    select firstonly inventTableModule
        where inventTableModule.ItemId == this.ItemId
            && inventTableModule.ModuleType == ModuleInventPurchSales::Sales;


    if(priceDiscTable.PriceUnit)
    {
        return priceDiscTable.Amount / priceDiscTable.PriceUnit * inventTableModule.PriceUnit;
    }
    else
    {
        return 0;
    }
}

