[SysClientCacheDataMethodAttribute(true)]
display Price dispNDX_BruttoVKP()
{
    return this.NDX_BruttoVKP();
}

/// <summary>
/// Displays a factor (Gross Selling Price / HK2 Price)
/// </summary>
/// <returns>Factor</returns>
public Price NDX_Faktor()
{
    Price       nDX_HK2, nDX_BruttoVKP;
    Price       retPrice = 0;

    nDX_HK2         = this.NDX_HK2();
    nDX_BruttoVKP   = this.NDX_BruttoVKP();

    if(nDX_HK2)
    {
        retPrice = nDX_BruttoVKP/nDX_HK2;
    }

    return retPrice;
}

