/// <summary>
/// returns HK2 factor from group for certain date
/// </summary>
/// <param name = "_transDate">TransDate, default system date</param>
/// <returns>KCS_HK2Factor</returns>
KCS_HK2Factor ndxGetHK2Factor(TransDate _transDate = DateTimeUtil::getSystemDate(DateTimeUtil::getUserPreferredTimeZone()))
{
    //Index only on groupid there are no records that have the same groupid(Maybe later)
    KCS_HK2FactorGroup  hk2FactorGroup  = KCS_HK2FactorGroup::findByRecId(this.NDXHK2GroupRefRecId);
    KCS_HK2Factor       hk2Factor       = hk2FactorGroup ? hk2FactorGroup.HK2Factor : 1;

    return hk2Factor;
}

/// <summary>
/// returns MGK factor from Group
/// </summary>
/// <returns>AVAMGKFactor</returns>
AVAMGKFactor ndxGetMGKFactor()
{
    AVAMGKFactors avaMGKFactors = AVAMGKFactors::findByRecId(this.inventTableModuleInvent().NDXMGKGroupRefRecId);
    AVAMGKFactor avaMGKFactor = avaMGKFactors ? avaMGKFactors.MGKFactor : 1;

    return avaMGKFactor;
}

/// <summary>
/// Displays HK2 price
/// </summary>
/// <returns>Price</returns>
[SysClientCacheDataMethodAttribute(true)]
public Price NDX_HK2()
{
    InventTableModule   inventTableModule;
    Price               retPrice;
    PriceUnit           salePriceUnit;

    select firstonly inventTableModule
        where inventTableModule.ItemId == this.ItemId
            && inventTableModule.ModuleType == ModuleInventPurchSales::Sales;

    salePriceUnit = inventTableModule.PriceUnit;

    if (!AVASalesParameters::find().HKFromSupportTable)
    {
        if(InventItemSetupSupplyType::getDefaultOrderType(this.ItemId, this.DataAreaId) ==  ReqPOType::Purch || this.itemGroupId() == 'ZHW')
        {
            select firstonly inventTableModule
            where inventTableModule.ItemId == this.ItemId
            && inventTableModule.ModuleType    == ModuleInventPurchSales::Purch;

            retPrice = inventTableModule.NDX_showHK2PriceDisc() / 1000 * salePriceUnit;
        }
        else
        {
            retPrice = this.KCS_GetHK2() * salePriceUnit;
        }
    }
    else
    {
        retPrice = AVAHK2NDG::getHK2p1000(this.ItemId) / 1000;
    }

    return retPrice;

}

