/// <summary>
/// Gets HK1 Price
/// </summary>
/// <param name = "inventDimId">invetnDimId</param>
/// <param name = "transDate">date</param>
/// <param name = "checkPrice">true or false</param>
/// <param name = "checkRights">true or false</param>
/// <param name = "costingVersionId">VersionId</param>
/// <returns>Price</returns>
Price KCS_GetHK1(InventDimId inventDimId = inventDim::inventDimIdBlank(), TransDate transDate = DateTimeUtil::getSystemDate(DateTimeUtil::getUserPreferredTimeZone()), boolean checkPrice = false, boolean checkRights = true, CostingVersionId  costingVersionId = '')
{
    InventItemPrice     inventItemPrice;
    Price price = 0;

    //security check in NDX_GetHK1InventItemPrice
    inventItemPrice = this.NDX_GetHK1InventItemPrice(inventDimId, transDate, checkPrice, checkRights, costingVersionId);

    if(inventItemPrice != null)
    {
        price = inventItemPrice.pcsPrice();
    }

    return price;
}

/// <summary>
/// Gets HK1 Price
/// </summary>
/// <param name = "_inventDimId">invetnDimId</param>
/// <param name = "_transDate">date</param>
/// <param name = "_checkPrice">true or false</param>
/// <param name = "_checkRights">true or false</param>
/// <param name = "_costingVersionId">VersionId</param>
/// <returns>Price</returns>
InventItemPrice NDX_GetHK1InventItemPrice(InventDimId _inventDimId = inventDim::inventDimIdBlank(), TransDate _transDate = DateTimeUtil::getSystemDate(DateTimeUtil::getUserPreferredTimeZone()), boolean _checkPrice = false,
    boolean _checkRights = true, CostingVersionId _costingVersionId = '')
{
    InventItemPrice     inventItemPrice;
    InventParameters    inventParameters    = InventParameters::find();
    InventSiteId        inventSiteId        = inventParameters.FallbackInventLocationId;
    CostingVersionId costingVersionId = _costingVersionId
    ;

    if(_checkRights && !xUserInfo::hasSecuritykeyAccess(privilegeStr(NDXHK1View)))
    {
        return null;
    }

    if (!costingVersionId)
    {
        costingVersionId = this.KCS_currentVersionId(_transDate);
    }

    if (!costingVersionId)
    {
        CostingVersion      costingVersion;
        select firstonly costingVersion
            order by KCS_ToDate desc, LastUpdate desc
            where costingVersion.Blocked == 0
             && (!costingVersion.DefaultDate || costingVersion.DefaultDate <= _transDate)
             && (!costingVersion.KCS_ToDate || costingVersion.KCS_ToDate >= _transDate);;

        costingVersionId = costingVersion.VersionId;

    }

    inventItemPrice = InventItemPrice::KCS_findCostingVersion(this.ItemId, costingVersionId, _transDate, this.KCS_defaultCostingPriceType(), _inventDimId);

    if (!inventItemPrice)
    {
        inventItemPrice = InventItemPrice::KCS_findCostingVersion(this.ItemId, costingVersionId, _transDate, this.KCS_defaultCostingPriceType(), _inventDimId, inventSiteId);
    }

    if (!inventItemPrice)
    {
        inventItemPrice = InventItemPrice::KCS_findCostingVersion(this.ItemId, costingVersionId, _transDate, CostingVersionPriceType::KCS_CALCalculatedPrice, _inventDimId);
        if (!inventItemPrice)
        {
            inventItemPrice = InventItemPrice::KCS_findCostingVersion(this.ItemId, costingVersionId, _transDate, CostingVersionPriceType::KCS_CALCalculatedPrice, _inventDimId, inventSiteId);
        }
    }

    if (!inventItemPrice.price() && _checkPrice)
    {
        warning("@NDX:NDXHK1NotFound");
    }

    return inventItemPrice;
}

/// <summary>
/// Gets HK2 price
/// </summary>
/// <param name = "inventDimId">invetnDimId</param>
/// <param name = "transDate">date</param>
/// <param name = "checkPrice">true or false</param>
/// <param name = "costingVersionId">VersionId</param>
/// <returns>Price</returns>
Price NDX_GetHK2(InventDimId inventDimId = inventDim::inventDimIdBlank(), TransDate transDate = DateTimeUtil::getSystemDate(DateTimeUtil::getUserPreferredTimeZone()), boolean checkPrice = false, CostingVersionId costingVersionId = '')
{
    Price               price;
    KCS_HK2FactorGroup  hK2FactorGroup;

    KCS_HK2Factor       hK2Factor       = 1000;
    Price               retPrice;

    price = this.KCS_GetHK1(inventDimId, transDate, checkPrice, false, costingVersionId);

    hK2FactorGroup = KCS_HK2FactorGroup::findByRecId(this.NDXHK2GroupRefRecId);
    if(hK2FactorGroup)
    {
        hk2Factor = hK2FactorGroup.HK2Factor * hK2Factor;
    }

    retPrice = Price * hK2Factor;

    return retPrice;
}

/// <summary>
/// Gets HK2 Price
/// </summary>
/// <param name = "inventDimId">InventDim id</param>
/// <param name = "transDate">date</param>
/// <param name = "checkPrice">true or false</param>
/// <returns>Price</returns>
Price KCS_GetHK2(InventDimId inventDimId = inventDim::inventDimIdBlank(), TransDate transDate = DateTimeUtil::getSystemDate(DateTimeUtil::getUserPreferredTimeZone()), boolean checkPrice = false)
{
    Price               price;           
    //KCS_HK2FactorGroup  hK2FactorGroup  = KCS_HK2FactorGroup::findDate(this.KCS_HK2GroupId, transDate);
    KCS_HK2FactorGroup  hK2FactorGroup;  

    KCS_HK2Factor       hK2Factor;

    hK2FactorGroup = KCS_HK2FactorGroup::findByRecId(this.NDXHK2GroupRefRecId);
    hK2Factor = hk2FactorGroup ? hK2FactorGroup.HK2Factor : 1;

    price = this.KCS_GetHK1(inventDimId, transDate, checkPrice, false);

    return price * hK2Factor;
}

