/// <summary>
/// DebuC 02.02.23
/// </summary>
public void update()
{
    InventTable orig = this.orig();
    next update();

    if(orig.NDXHK2GroupRefRecId!= this.NDXHK2GroupRefRecId)
    {
        NDXHK2GroupHistory::createByInventTable(this, orig);
    }

    if(orig.NetWeight != this.NetWeight)
    {
        NDXItemNetWeightHistory::createByInventTable(this, orig);
    }
}

/// <summary>
/// Checks if item has showinfoitemstate set for items state
/// </summary>
/// <returns>true or false</returns>
boolean hasItemStateWithInfo()
{
    NDXItemStateTable lNDXItemStateTable;

    if (this.KCS_KAOItemState)
    {
        lNDXItemStateTable = NDXItemStateTable::find(this.ItemId);
        return (lNDXItemStateTable && lNDXItemStateTable.ShowInfoItemState && lNDXItemStateTable.InfoItemState);
    }
    return false;
}

