/// <summary>
/// Delivery unit as text
/// </summary>
/// <param name = "l_NDX_DeliveryUnitPrefMultipleQty">qantity</param>
/// <param name = "l_NDX_InventItemSetupMultipleQty">multipla qantity</param>
/// <param name = "l_UnitID">unit id</param>
/// <returns>delivery unit as string</returns>
static NDXDeliveryUnitTxt NDX_DeliveryUnitTxt(real l_NDX_DeliveryUnitPrefMultipleQty, real l_NDX_InventItemSetupMultipleQty, UnitIDBase l_UnitID)
{
    #define.IntBarrier(0.1)
    NDXDeliveryUnitTxt      deliveryUnitTxt;
    str                     txtDeliveryUnitPref, txtInventItemSetup;
    real                    diffValue;

    // Prüfung, ob MultipleQty mit Nachkommastelle dargestellt werden muss
    diffValue = abs(l_NDX_DeliveryUnitPrefMultipleQty - real2int(l_NDX_DeliveryUnitPrefMultipleQty));
    if ( diffValue > #IntBarrier)
    {
        txtDeliveryUnitPref = num2str(decround(l_NDX_DeliveryUnitPrefMultipleQty,1), -1,1,-1,-1);
    }
    else
    {
        txtDeliveryUnitPref = num2str0(l_NDX_DeliveryUnitPrefMultipleQty, -1);
    }

    diffValue = abs(l_NDX_InventItemSetupMultipleQty - real2int(l_NDX_InventItemSetupMultipleQty));

    if ( diffValue > #IntBarrier)
    {
        txtInventItemSetup = num2str(decround(l_NDX_InventItemSetupMultipleQty,1), -1,1,-1,-1);
    }
    else
    {
        txtInventItemSetup = num2str0(l_NDX_InventItemSetupMultipleQty, -1);
    }

    if (l_NDX_DeliveryUnitPrefMultipleQty  == 1 && l_NDX_InventItemSetupMultipleQty   == 1)
    {
        deliveryUnitTxt  = strfmt('%1 %2', txtInventItemSetup, l_UnitID);       // %1 %2
    }
    else if (l_NDX_DeliveryUnitPrefMultipleQty == 1)
    {
        deliveryUnitTxt  = strfmt('%1 %2', txtInventItemSetup, l_UnitID);       // %1 %2
    }
    else if (l_NDX_InventItemSetupMultipleQty == 1)
    {
        deliveryUnitTxt  = strfmt('%1 %2', txtDeliveryUnitPref, l_UnitID);       // %1 %2
    }
    else
    {
        deliveryUnitTxt  = strfmt('%1 x %2 %3', txtDeliveryUnitPref,
                                          txtInventItemSetup,
                                          l_UnitID);       // %1 x %2 %3
    }
    return deliveryUnitTxt;
}

