/// <summary>
/// PaffH 25.04.24
/// </summary>
/// <returns>mapped OV-Item</returns>
ItemId NDXMappedItemidOVItem()
{
    const str OVItemMarker = 'OV';
    str mappedItemid = '';
    int x;
    if (substr(this.ItemId, strlen(this.ItemId), -2) == OVItemMarker)
    {
        mappedItemid = substr(this.ItemId, 1, strlen(this.ItemId) - 2);
        if (!InventTable::find(mappedItemid))
        {
            mappedItemid = '';
        }
        else
        {
            x = 1;
        }
    }
    return mappedItemid;
}
